            self._limits = []

    def set_limit(self, category: str, month: str, limit: str) -> None:
        limit_val = Decimal(limit)
        if limit_val < 0:
            raise ValidationError("budget limit must be non-negative")
        self._limits.append(BudgetLimit(category, month, limit_val))

    def get_limit(self, category: str, month: str) -> BudgetLimit | None:
        for row in self._limits:
            if row.category == category and row.month == month:
                return row
        return None

    def remove_limit(self, category: str, month: str) -> BudgetLimit:
        for i, row in enumerate(self._limits):
            if row.category == category and row.month == month:
                return self._limits.pop(i)
        raise KeyError(f"no budget limit for {category} in {month}")

    @property
    def limits(self):
        return self._limits

    def to_dict(self):
        return [row.to_dict() for row in self._limits]

